#!/usr/bin/env python3
"""Embed a Riftlock Ed25519 server public key in the client source."""

from __future__ import annotations

import argparse
from pathlib import Path


HEADER = """#pragma once

// Generated by tools/configure_riftlock_public_key.py.
#define RIFTLOCK_PUBLIC_KEY_CONFIGURED 1

static const unsigned char kRiftlockServerPublicKey[32] = {{
{rows}
}};
"""


def parse_key(value: str) -> bytes:
	compact = "".join(value.split())
	try:
		key = bytes.fromhex(compact)
	except ValueError as error:
		raise argparse.ArgumentTypeError("public key must be hexadecimal") from error
	if len(key) != 32:
		raise argparse.ArgumentTypeError("public key must contain exactly 32 bytes")
	if not any(key):
		raise argparse.ArgumentTypeError("the all-zero public key is not valid")
	return key


def render(key: bytes) -> str:
	rows = []
	for offset in range(0, len(key), 8):
		rows.append("\t" + ", ".join(f"0x{byte:02X}" for byte in key[offset : offset + 8]) + ",")
	rows[-1] = rows[-1].rstrip(",")
	return HEADER.format(rows="\n".join(rows))


def main() -> int:
	parser = argparse.ArgumentParser(description=__doc__)
	parser.add_argument("public_key", type=parse_key, help="32-byte Ed25519 public key in hexadecimal")
	parser.add_argument(
		"--output",
		type=Path,
		default=Path(__file__).resolve().parents[1]
		/ "CustomDLL"
		/ "src"
		/ "riftlock"
		/ "riftlock_public_key.h",
	)
	args = parser.parse_args()
	args.output.parent.mkdir(parents=True, exist_ok=True)
	args.output.write_text(render(args.public_key), encoding="utf-8", newline="\n")
	print(f"Embedded Riftlock public key in {args.output}")
	return 0


if __name__ == "__main__":
	raise SystemExit(main())
